/**
 * Common Zod schemas shared across API routes
 * 
 * Provides centralized schema definitions for common validation patterns
 * used throughout the API, ensuring consistency and reducing duplication.
 */

import { z } from 'zod';

/**
 * Validation schema for entity IDs (nanoid format)
 * Matches IDs generated by nanoid: 10-30 characters, alphanumeric with hyphens and underscores
 */
export const IdSchema = z.string().regex(/^[a-z0-9_-]{10,30}$/i, 'Invalid ID format');

/**
 * Validation schema for slug fields
 * Used for human-readable identifiers in URLs and API paths
 */
export const SlugSchema = z
  .string()
  .min(1, 'Slug cannot be empty')
  .max(255, 'Slug must be less than 255 characters')
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'Slug must be lowercase alphanumeric with hyphens');

/**
 * Validation schema for pagination parameters
 * Provides consistent pagination across all list endpoints
 */
export const PaginationSchema = z.object({
  page: z.coerce.number().int().min(1).default(1).optional(),
  limit: z.coerce.number().int().min(1).max(100).default(20).optional(),
  offset: z.coerce.number().int().min(0).optional(),
});

/**
 * Validation schema for email addresses
 * Ensures consistent email validation across all endpoints
 */
export const EmailSchema = z
  .string()
  .email('Invalid email format')
  .max(255, 'Email must be less than 255 characters');

/**
 * Validation schema for passwords
 * Enforces minimum password requirements
 */
export const PasswordSchema = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .max(255, 'Password must be less than 255 characters');

/**
 * Validation schema for environment variable keys
 * Matches the pattern for environment variable names
 */
export const EnvironmentKeySchema = z
  .string()
  .min(1, 'Key cannot be empty')
  .max(255, 'Key must be less than 255 characters')
  .regex(/^[A-Z][A-Z0-9_]*$/, 'Key must be uppercase alphanumeric with underscores, starting with a letter');

/**
 * Validation schema for OAuth providers
 */
export const OAuthProviderSchema = z.enum(['google', 'github']);

/**
 * Validation schema for sorting parameters
 */
export const SortOrderSchema = z.enum(['asc', 'desc']).default('desc').optional();

/**
 * Validation schema for timestamps
 */
export const TimestampSchema = z.string().datetime({ message: 'Invalid timestamp format' });